<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/amazon-returns/TenantPersistence.php';
require_once __DIR__.'/../includes/amazon-returns/AdminCaseOverride.php';
function acs(bool $v,string $m):void{if(!$v)throw new RuntimeException($m);}
function acsThrows(callable $f,string $m):void{try{$f();}catch(InvalidArgumentException|RuntimeException){return;}throw new RuntimeException($m);}
$db=new PDO('sqlite::memory:');$db->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);
$db->exec("CREATE TABLE amazon_return_cases (id INTEGER PRIMARY KEY,tenant_id INTEGER,amazon_connection_id INTEGER,amazon_order_id TEXT,amazon_order_item_id TEXT,marketplace_id TEXT,quantity_ordered INTEGER,quantity_refunded INTEGER,quantity_received INTEGER,program TEXT,refund_initiator TEXT,refund_at TEXT,seller_debit_at TEXT,refund_amount NUMERIC,expected_reimbursement_amount NUMERIC,reconciled_credit_amount NUMERIC,physical_status TEXT,state TEXT,policy_version_id INTEGER,eligibility_at TEXT,next_action_at TEXT,safe_t_id TEXT,support_case_id TEXT,repeated_denial_count INTEGER,last_denial_fingerprint TEXT,appeal_deadline_at TEXT,terminal_reason TEXT,closed_at TEXT,updated_at TEXT)");
$db->exec("CREATE TABLE amazon_return_events (id INTEGER PRIMARY KEY AUTOINCREMENT,tenant_id INTEGER,amazon_connection_id INTEGER,case_id INTEGER,event_type TEXT,source TEXT,source_event_id TEXT,idempotency_key TEXT,occurred_at TEXT,payload_json TEXT,evidence_sha256 TEXT,created_at TEXT,UNIQUE(tenant_id,amazon_connection_id,idempotency_key))");
$db->exec("CREATE TABLE amazon_return_overrides (id INTEGER PRIMARY KEY AUTOINCREMENT,tenant_id INTEGER,amazon_connection_id INTEGER,case_id INTEGER,actor_id INTEGER,reason TEXT,before_json TEXT,after_json TEXT,created_at TEXT)");
$db->exec("INSERT INTO amazon_return_cases (id,tenant_id,amazon_connection_id,amazon_order_id,amazon_order_item_id,marketplace_id,quantity_ordered,quantity_refunded,quantity_received,program,refund_initiator,refund_amount,expected_reimbursement_amount,reconciled_credit_amount,physical_status,state,updated_at,closed_at,terminal_reason) VALUES (41,7,11,'701-1234567-1234567','item-1','A2Q3Y263D00KWC',1,1,0,'FBA_ONSITE','AMAZON_AUTOMATIC',121.50,121.50,0,'NOT_RECEIVED','CLOSED_LOSS','2026-11-12 20:00:00','2026-11-12 19:00:00','AUTO_LOSS')");
$p=SvAmazonTenantPersistence::create($db,new SvAmazonTenantContext(7,11,99));
$first=SvAmazonAdminCaseOverride::apply($p,41,'REOPEN',[],'Reavaliar manualmente','admin@example.test','request-0001','2026-11-12 20:00:00');
$overlayMethod=new ReflectionMethod(SvAmazonReturnCaseRepository::class,'applyAdminOverridePatch');$overlayMethod->setAccessible(true);
$autonomousPatch=$overlayMethod->invoke($p->cases,41,['state'=>'SAFE_T_APPROVED','refund_amount'=>'130.00','next_action_at'=>'2026-11-13 00:00:00']);
acs($autonomousPatch['state']==='POLICY_REVIEW_REQUIRED','Autonomous state writes must respect an active admin state override.');
acs((string)$autonomousPatch['refund_amount']==='130.00','Unmodified source-backed fields must continue to update autonomously.');
acs($autonomousPatch['next_action_at']==='2026-11-13 00:00:00','Autonomous scheduling must remain in control of next_action_at.');
acs($first['override_id']>0&&$first['event_id']>0,'Override and event must persist.');
acs($first['case']['state']==='POLICY_REVIEW_REQUIRED'&&$first['case']['closed_at']===null,'Closed case must reopen regardless of previous state.');
acs((float)$first['case']['reconciled_credit_amount']===0.0,'Reopen must not change reconciled credit.');
acs((int)$db->query('SELECT COUNT(*) FROM amazon_return_overrides')->fetchColumn()===1,'Exactly one override row must be written.');
$replay=SvAmazonAdminCaseOverride::apply($p,41,'REOPEN',[],'Reavaliar manualmente','admin@example.test','request-0001','2026-11-12 20:00:00');
acs($replay['idempotent_replay']===true,'Same request must be idempotent.');
acs((int)$db->query('SELECT COUNT(*) FROM amazon_return_events')->fetchColumn()===1,'Replay must not duplicate event.');
$updated=(string)$p->cases->find(41)['updated_at'];
$recovered=SvAmazonAdminCaseOverride::apply($p,41,'MARK_RECOVERED',[],'Classificação administrativa, crédito ainda não conciliado','admin@example.test','request-0002',$updated);
$updated=(string)$p->cases->find(41)['updated_at'];
$manualAmount=SvAmazonAdminCaseOverride::apply($p,41,'UPDATE_FIELDS',['refund_amount'=>'100.00'],'Correção administrativa do valor esperado','admin@example.test','request-0010',$updated);
$afterAutomation=$overlayMethod->invoke($p->cases,41,['state'=>'SAFE_T_APPROVED','refund_amount'=>'140.00','reconciled_credit_amount'=>'10.00']);
acs($afterAutomation['state']==='RECOVERED','Autonomous state writes must not replace a manual recovered classification.');
acs((float)$afterAutomation['refund_amount']===100.0,'An explicitly edited field must remain the active administrative value.');
acs((float)$afterAutomation['reconciled_credit_amount']===10.0,'Financial reconciliation must continue updating real credit.');
acs($recovered['case']['state']==='RECOVERED','Admin may choose recovered classification.');
acs((float)$recovered['case']['reconciled_credit_amount']===0.0,'Recovered classification must not fabricate financial credit.');
$updated=(string)$p->cases->find(41)['updated_at'];
acsThrows(fn()=>SvAmazonAdminCaseOverride::apply($p,41,'UPDATE_FIELDS',['reconciled_credit_amount'=>'121.50'],'não','admin@example.test','request-0003',$updated),'Admin cannot alter reconciled credit.');
acsThrows(fn()=>SvAmazonAdminCaseOverride::apply($p,41,'SET_STATE',['state'=>'NOT_A_STATE'],'não','admin@example.test','request-0004',$updated),'Unknown state must be rejected.');
acsThrows(fn()=>SvAmazonAdminCaseOverride::apply($p,41,'CLOSE_LOSS',[],'','admin@example.test','request-0005',$updated),'Reason is mandatory.');
acsThrows(fn()=>SvAmazonAdminCaseOverride::apply($p,41,'CLOSE_LOSS',[],'stale','admin@example.test','request-0006','2026-11-12 20:00:00'),'Stale version must be rejected.');
acs((int)$db->query('SELECT COUNT(*) FROM amazon_return_overrides')->fetchColumn()===3,'Rejected actions must not create partial audit rows.');
$updated=(string)$p->cases->find(41)['updated_at'];
$review=SvAmazonAdminCaseOverride::apply($p,41,'REQUEST_REVIEW',[],'Revisão solicitada pelo administrador','admin@example.test','request-0007',$updated);
acs($review['case']['state']==='POLICY_REVIEW_REQUIRED','Admin may request review from any state.');
$updated=(string)$p->cases->find(41)['updated_at'];
$contest=SvAmazonAdminCaseOverride::apply($p,41,'PREPARE_CONTESTATION',[],'Preparar contestação administrativa','admin@example.test','request-0008',$updated);
acs($contest['case']['state']==='POLICY_REVIEW_REQUIRED','Admin may prepare contestation without external write.');
$updated=(string)$p->cases->find(41)['updated_at'];
$setState=SvAmazonAdminCaseOverride::apply($p,41,'SET_STATE',['state'=>'SAFE_T_SUBMITTED'],'Classificação administrativa solicitada','admin@example.test','request-0011',$updated);
acs($setState['case']['state']==='SAFE_T_SUBMITTED','Admin may select any valid domain state independent of prior state.');
$updated=(string)$p->cases->find(41)['updated_at'];
$loss=SvAmazonAdminCaseOverride::apply($p,41,'CLOSE_LOSS',[],'Encerramento manual','admin@example.test','request-0009',$updated);
acs($loss['case']['state']==='CLOSED_LOSS','Admin may close a previously recovered/reviewed case.');
acs((int)$db->query('SELECT COUNT(*) FROM amazon_return_overrides')->fetchColumn()===7,'All valid interventions must be persisted exactly once.');
$event=json_decode((string)$db->query("SELECT payload_json FROM amazon_return_events WHERE event_type='ADMIN_CASE_OVERRIDE' ORDER BY id DESC LIMIT 1")->fetchColumn(),true);
acs(($event['external_operation']??null)==='NOT_REQUESTED','Manual override must not claim external Amazon operation.');
echo "admin-case-override-service-test: OK\n";
